import {KART as C,KART_ACTIVITY} from './kart-layout.js';
import {BUMPER,bumperBoardFrame} from './bumper-ride.js';
import {bumperPoseBottom} from './bumper-support.js';
import {kartOutwardWalkY} from './kart-support.js';
import {KART_TRACK as T,kartTrackPoint,kartTrackProgress,kartClearSegment,KartLap} from './kart-track.js';
export {KART_ACTIVITY} from './kart-layout.js';
const STEP=1/120,EPS=1e-9,clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),ease=t=>{t=clamp(t,0,1);return t*t*t*(10+t*(-15+6*t));},delta=(a,b)=>Math.atan2(Math.sin(b-a),Math.cos(b-a));
function local(p){return{x:C.dock.z-p.z,y:p.y,z:p.x-C.dock.x,yaw:p.yaw-C.dock.yaw};}
function world(p){return{...p,x:C.dock.x+p.z,z:C.dock.z-p.x,yaw:p.yaw+C.dock.yaw,carX:C.dock.x,carZ:C.dock.z,carYaw:C.dock.yaw};}
export function kartBoardFrame(from,time){const a=local(from),p=bumperBoardFrame({...a,x:a.x+BUMPER.dock.x,z:a.z+BUMPER.dock.z},time);return world({...p,x:p.x-BUMPER.dock.x,z:p.z-BUMPER.dock.z});}
export function kartExitFrame(time){const t=clamp(time,0,C.mountDuration),p={x:0,y:C.rootY,z:0,yaw:0,pitch:0,roll:0,pose:1,bumperRamp:ease(t/.3),walk:0,walkTime:0};if(t<.3)return world(p);if(t<1.3)return world({...p,z:.75*ease(t-.3)});if(t<2.1){const pose=1-ease((t-1.3)/.8);return world({...p,z:.75,y:C.seatTop-bumperPoseBottom(pose),pose});}const q=(t-2.1)/(C.mountDuration-2.1),progress=ease(q),z=.75+2.6*progress,walk=.25*ease(q/.12)*ease((1-q)/.12),walkTime=2.6*progress*1.5,stride=walk*Math.sin(Math.floor(walkTime*20)/20*8);return world({...p,z,y:kartOutwardWalkY(z,stride),pose:0,walk,walkTime});}
/** A transient fixed-step driving owner; no timers, save writes, meshes, or random state. */
export class KartRaceRide{
 constructor(activity,from){this.activity={...activity,exit:{...activity.exit}};this.from={...from};this.phase='entering';this.raceState='boarding';this.elapsed=0;this.activeTime=0;this.raceTime=0;this.countdown=3;this.x=C.dock.x;this.z=C.dock.z;this.yaw=C.dock.yaw;this.speed=0;this.throttle=0;this.steer=0;this.accumulator=0;this.paused=false;this.exitRequested=false;this.done=false;this.dismount=false;this.reverseTime=null;this.returnStage='brake';this.lap=new KartLap();}
 setReduced(){}
 setIntent(throttle=0,steer=0){const allowed=!this.paused&&!this.exitRequested&&this.phase==='active'&&this.raceState==='racing';this.throttle=allowed&&Number.isFinite(throttle)?clamp(throttle,-1,1):0;this.steer=allowed&&Number.isFinite(steer)?clamp(steer,-1,1):0;}
 pause(){this.paused=true;this.throttle=this.steer=this.speed=this.accumulator=0;}
 resume(){if(!this.done)this.paused=false;}
 requestExit(){if(this.exitRequested||this.done)return false;this.exitRequested=true;this.throttle=this.steer=0;if(this.phase==='entering'){this.reverseTime=this.elapsed;this.dismount=true;this.activity.exit={x:this.from.x,z:this.from.z,yaw:this.from.yaw};}this.phase='exiting';this.elapsed=0;return true;}
 update(dt){if(this.done||this.paused||!Number.isFinite(dt)||dt<=0)return;this.accumulator+=Math.min(dt,.1);while(this.accumulator>=STEP-1e-10){this.accumulator=Math.max(0,this.accumulator-STEP);this.advance(STEP);if(this.done)break;}}
 advance(dt){this.elapsed+=dt;if(this.phase==='entering'){if(this.elapsed>=C.mountDuration-EPS){this.phase='active';this.raceState='countdown';this.elapsed=0;}return;}if(this.dismount){if(this.elapsed>=(this.reverseTime??C.mountDuration)-EPS){this.done=true;this.phase='idle';}return;}if(this.phase==='exiting'){this.dock(dt);return;}this.activeTime+=dt;if(this.raceState==='countdown'){this.countdown=Math.max(0,3-this.elapsed);if(!this.countdown){this.raceState='racing';this.elapsed=0;}return;}if(this.raceState==='finished'){this.speed=Math.max(0,this.speed-C.brake*dt);this.move(Math.sin(this.yaw)*this.speed*dt,Math.cos(this.yaw)*this.speed*dt);return;}this.raceTime+=dt;this.yaw=delta(0,this.yaw+this.steer*C.turnSpeed*dt*(this.speed<0?-1:1));const opposite=this.speed*this.throttle<0,target=this.throttle===0||opposite?0:this.throttle>0?C.maxSpeed*this.throttle:C.reverseSpeed*this.throttle,rate=this.throttle===0||opposite?C.brake:C.acceleration;this.speed+=clamp(target-this.speed,-rate*dt,rate*dt);if(Math.abs(this.speed)<1e-12)this.speed=0;this.move(Math.sin(this.yaw)*this.speed*dt,Math.cos(this.yaw)*this.speed*dt);}
 move(dx,dz){const a={x:this.x,z:this.z},b={x:this.x+dx,z:this.z+dz};if(!kartClearSegment(a,b)){let low=0,high=1;for(let i=0;i<35;i++){const t=(low+high)/2;if(kartClearSegment(a,{x:a.x+dx*t,z:a.z+dz*t}))low=t;else high=t;}b.x=a.x+dx*low;b.z=a.z+dz*low;this.speed=0;}this.x=b.x;this.z=b.z;if(!this.exitRequested&&this.raceState==='racing'&&this.lap.cross(a,b)){this.raceState='finished';this.throttle=this.steer=0;}}
 dock(dt){if(this.returnStage==='brake'){const old=this.speed;this.speed+=clamp(-this.speed,-C.brake*dt,C.brake*dt);this.move(Math.sin(this.yaw)*(old+this.speed)*.5*dt,Math.cos(this.yaw)*(old+this.speed)*.5*dt);if(Math.abs(this.speed)<EPS){this.speed=0;this.returnS=kartTrackProgress(this);this.returnPoint=kartTrackPoint(this.returnS);this.returnStage='center';}return;}if(this.returnStage==='center'){const dx=this.returnPoint.x-this.x,dz=this.returnPoint.z-this.z,d=Math.hypot(dx,dz);if(d>1e-8){const turn=delta(this.yaw,Math.atan2(dx,dz));this.yaw+=clamp(turn,-dt*1.4,dt*1.4);if(Math.abs(turn)>.02)return;const n=Math.min(d,1.8*dt);this.move(dx/d*n,dz/d*n);return;}const turn=delta(this.yaw,this.returnPoint.yaw);this.yaw+=clamp(turn,-dt*1.4,dt*1.4);if(Math.abs(turn)>.02)return;this.yaw=this.returnPoint.yaw;const forward=(T.length-this.returnS)%T.length;this.returnDirection=this.returnS<forward?-1:1;this.returnRemaining=Math.min(this.returnS,forward);this.returnStage='follow';return;}if(this.returnRemaining>EPS){const step=Math.min(this.returnRemaining,(this.returnDirection<0?1.8:2.4)*dt),next=kartTrackPoint(this.returnS+step*this.returnDirection);if(!kartClearSegment(this,next)){this.pause();return;}this.x=next.x;this.z=next.z;this.yaw=next.yaw;this.returnS+=step*this.returnDirection;this.returnRemaining-=step;return;}this.x=C.dock.x;this.z=C.dock.z;this.yaw=C.dock.yaw;this.dismount=true;this.elapsed=0;}
 sample(){if(this.phase==='entering')return kartBoardFrame(this.from,this.elapsed);if(this.dismount)return this.reverseTime!==null?kartBoardFrame(this.from,Math.max(0,this.reverseTime-this.elapsed)):kartExitFrame(this.elapsed);return{x:this.x,y:C.rootY,z:this.z,yaw:this.yaw,pitch:0,roll:0,pose:1,carX:this.x,carZ:this.z,carYaw:this.yaw,bumperRamp:0,walk:0,walkTime:0,speed:this.speed,steer:this.exitRequested?(this.returnStage==='follow'&&Math.abs(this.x)>6?1:0):this.steer};}
 cancel(){this.done=true;this.phase='idle';this.throttle=this.steer=this.speed=this.accumulator=0;return this.activity.exit;}
}
